            q[i][j] = mul_mod(q[i][j], val);
        }
    }
    dp[0][0] = 1;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < time_stamp; ++j) {
            for (int k = 0; k < (1 << n); ++k) {
                int next_state = child[j][k];
                dp[i + 1][next_state] = add_mod(dp[i + 1][next_state], mul_mod(dp[i][j], q[i][k]));
            }
        }
    }
    bs128 result;
    for (int i = 0; i < (1 << n); ++i) result[i] = 1;
    cout << dp[n][index_map[result]] << endl;
