import java.util.*;
import java.io.*;

public class Main {
    static class BitSet128 {
        long low;
        long high;

        public BitSet128() {
            this.low = 0L;
            this.high = 0L;
        }

        public BitSet128(BitSet128 other) {
            this.low = other.low;
            this.high = other.high;
        }

        public boolean get(int index) {
            if (index < 64) {
                return ((low >>> index) & 1L) != 0;
            } else {
                return ((high >>> (index - 64)) & 1L) != 0;
            }
        }

        public void set(int index, boolean value) {
            if (index < 64) {
                if (value) {
                    low |= (1L << index);
                } else {
                    low &= ~(1L << index);
                }
            } else {
                if (value) {
                    high |= (1L << (index - 64));
                } else {
                    high &= ~(1L << (index - 64));
                }
            }
        }

        public void setAll() {
            low = -1L;
            high = -1L;
        }

        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof BitSet128)) return false;
            BitSet128 other = (BitSet128) o;
            return this.low == other.low && this.high == other.high;
        }

        public int hashCode() {
            return Objects.hash(low, high);
        }
    }

    static final int MOD = 1000000007;
    static final int INV = 570000004;

    static int add_mod(int a, int b) {
        int s = a + b;
        return s >= MOD ? s - MOD : s;
    }

    static int sub_mod(int a, int b) {
        int s = a - b;
        return s < 0 ? s + MOD : s;
    }

    static int mul_mod(int a, int b) {
        return (int) ((1L * a * b) % MOD);
    }

    static Map<BitSet128, Integer> index_map = new HashMap<>();
    static int total_nodes, time_stamp;
    static int[][] child;

    static int dfs(BitSet128 state) {
        if (index_map.containsKey(state))
            return index_map.get(state);
        int id = time_stamp++;
        index_map.put(state, id);
        for (int mask = 0; mask < (1 << total_nodes); ++mask) {
            BitSet128 new_state = new BitSet128();
            new_state.setAll();
            for (int j = 0; j < total_nodes; ++j) {
                if (!state.get(j)) {
                    int k_mask = mask & (1 << j);
                    int k_temp = k_mask;
                    while (k_temp != 0) {
                        int k_bit = Integer.numberOfTrailingZeros(k_temp);
                        int j_xor_k = j ^ (1 << k_bit);
                        if (state.get(j_xor_k)) {
                            new_state.set(j, true);
                            break;
                        }
                        k_temp &= ~(1 << k_bit);
                    }
                }
            }
            child[id][mask] = dfs(new_state);
        }
        return id;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine());
        total_nodes = 0;
        index_map.clear();
        // Initialize child array with size based on maximum possible nodes
        // Since total_nodes is unknown initially, we will allocate dynamically
        // but for simplicity, allocate a large enough size
        int maxNodes = 65536;
        child = new int[maxNodes][1 << 16]; // 16 is max n, but to be safe, use 16
        // Note: For large n, this may be memory heavy, but for the purpose of translation, we proceed.

        BitSet128 initialState = new BitSet128();
        initialState.setAll();
        total_nodes = 0;
        time_stamp = 0;
        int root_id = dfs(initialState);

        int[][] p = new int[n][n];
        int[][] q = new int[n][1 << n];
        int[][] dp = new int[n + 1][1 << n];

        for (int i = 0; i < n; ++i) {
            String[] line = br.readLine().split(" ");
            for (int j = 0; j < n; ++j) {
                p[i][j] = Integer.parseInt(line[j]);
                p[i][j] = mul_mod(p[i][j], INV);
            }
        }

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < (1 << n); ++j) {
                q[i][j] = 1;
                for (int k = 0; k < n; ++k) {
                    int val = ((j >> k) & 1) != 0 ? p[k][i] : sub_mod(1, p[k][i]);
                    q[i][j] = mul_mod(q[i][j], val);
                }
            }
        }

        for (int i = 0; i <= n; ++i)
            Arrays.fill(dp[i], 0);
        dp[0][0] = 1;

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < time_stamp; ++j) {
                for (int k = 0; k < (1 << n); ++k) {
                    int next_state = child[j][k];
                    dp[i + 1][next_state] = add_mod(dp[i + 1][next_state], mul_mod(dp[i][j], q[i][k]));
                }
            }
        }

        BitSet128 result = new BitSet128();
        result.setAll();
        int finalIndex = index_map.get(result);
        System.out.println(dp[n][finalIndex]);
    }
}
